head.b:skin:
/* ILLUMINISMO  tokens (STYLE.md 13) */
:root{--bg:#11110f;--panel:#1a1a16;--line:#37362c;--gold:#d5b978;--text:#f1eee4;--muted:#aaa79a;--paper:#e8dfc9;--ink:#272720;
--serif:Georgia,"Noto Serif Georgian",serif;--sans:Arial,"Noto Sans Georgian",sans-serif;color-scheme:dark}
*{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);line-height:1.8;font-size:16px}
a{color:inherit;text-decoration:none}a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid var(--gold);outline-offset:4px}
img{max-width:100%;height:auto}
h1,h2,h3{font-family:var(--serif);font-weight:400}
h1{font-size:clamp(2.1rem,4.1vw,4.2rem);line-height:1.3;letter-spacing:-.035em;margin:.2em 0 .5em}
h2{font-size:1.9rem;line-height:1.45}h3{font-size:1.35rem}
.skip{position:absolute;left:-999px;top:8px;background:var(--gold);color:#161610;padding:8px 14px;z-index:99}.skip:focus{left:8px}
.wrap{max-width:1480px;margin:auto;padding:0 5%}
/* header */
.site-header{border-bottom:1px solid var(--line);position:sticky;top:0;background:rgba(17,17,15,.94);backdrop-filter:blur(6px);z-index:20}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:24px;padding-top:18px;padding-bottom:18px;flex-wrap:wrap}
.brand{display:flex;align-items:center;gap:14px;font-family:var(--serif);font-size:1.2rem;letter-spacing:.15em;line-height:1.3}
.brand-mark{border:1px solid var(--gold);width:32px;height:42px;display:grid;place-items:center;color:var(--gold);font-size:1.55rem}
.brand small{display:block;font-family:var(--sans);letter-spacing:.12em;color:var(--muted);font-size:.7rem;margin-top:4px}
.menu ul{list-style:none;display:flex;gap:22px;margin:0;padding:0;flex-wrap:wrap}
.menu a{color:var(--muted);font-size:.9rem;padding:6px 0;border-bottom:1px solid transparent}.menu a:hover,.menu a.active{color:var(--gold);border-color:var(--gold)}
.tools{display:flex;gap:12px;align-items:center}
.search-form{display:flex;border:1px solid var(--line)}.search-form input{background:transparent;border:0;color:var(--text);padding:8px 10px;width:150px;font-family:var(--sans)}
.search-form button{background:transparent;border:0;color:var(--gold);padding:0 10px;cursor:pointer}
.lang button{background:transparent;border:1px solid var(--line);color:var(--muted);padding:6px 10px;cursor:pointer;font-size:.8rem}.lang button[aria-pressed=true]{color:var(--gold);border-color:var(--gold)}
/* progress (F-PROGRESS) */
#read-progress{position:fixed;top:0;left:0;height:2px;background:var(--gold);width:0;z-index:30}
/* text */
.eyebrow{text-transform:uppercase;color:var(--gold);font-size:.8rem;letter-spacing:.08em;margin:0 0 14px}
.lede{font-size:1.08rem;color:#c7c4b6;max-width:680px;line-height:1.95}
.gold{display:inline-block;background:var(--gold);color:#161610;border:1px solid var(--gold);padding:13px 20px;font-weight:600;font-size:.9rem;min-height:48px}
.quiet{color:var(--gold);border-bottom:1px solid var(--line);font-size:.9rem}
.muted{color:var(--muted)}
/* hero */
.hero{padding:70px 0 50px;border-bottom:1px solid var(--line)}
.hero h1{max-width:900px}
/* section */
.block{padding:56px 0;border-bottom:1px solid var(--line)}
.section,.widget{margin:0}
.wrap.section{padding:0 5%}
.section-head{display:flex;justify-content:space-between;align-items:baseline;gap:20px;margin-bottom:26px;flex-wrap:wrap}
.section-head h2{margin:0}
/* works gallery (F-CATALOG) */
.filters{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 22px}
.filters button{background:transparent;border:1px solid var(--line);color:var(--muted);padding:6px 12px;font-size:.82rem;cursor:pointer}
.filters button[aria-pressed=true]{color:var(--gold);border-color:var(--gold)}
.works{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:20px}
.work{background:var(--panel);border:1px solid var(--line);display:flex;flex-direction:column;transition:border-color .2s}
.work:hover{border-color:var(--gold)}
.work img{aspect-ratio:1200/630;object-fit:cover;width:100%;display:block;background:#000}
.work-body{padding:16px 18px 20px}.work-body h3{margin:4px 0 6px}.work-body p{margin:0;color:var(--muted);font-size:.92rem}
.work .tag{font-size:.72rem;color:var(--gold);text-transform:uppercase;letter-spacing:.08em}
/* post cards */
.posts{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:26px}
.card{border-top:1px solid var(--line);padding-top:18px}
.card img{width:100%;aspect-ratio:16/9;object-fit:cover;border:1px solid var(--line);margin-bottom:14px;display:block}
.card h3{margin:2px 0 8px;font-size:1.4rem;line-height:1.4}.card h3 a:hover{color:var(--gold)}
.card p{color:#c7c4b6;margin:0 0 10px;font-size:.95rem}
.meta{color:var(--muted);font-size:.82rem;display:flex;gap:14px;flex-wrap:wrap}
/* article */
.article{max-width:760px;margin:0 auto;padding:56px 0 30px}
.article-head{margin-bottom:30px}
.post-body{font-family:var(--serif);font-size:1.12rem;line-height:1.95}
.post-body > p:first-of-type::first-letter{float:left;font-size:3.6rem;line-height:1;padding:8px 12px 0 0;color:var(--gold)}
.post-body h2{font-size:1.65rem;margin:2em 0 .6em}.post-body h3{margin:1.6em 0 .5em}
.post-body a{color:var(--gold);border-bottom:1px solid var(--line)}
.post-body blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:2px solid var(--gold);color:#d9d5c6}
.post-body img{border:1px solid var(--line)}
.post-body figure{margin:1.8em 0}.post-body figcaption{font-family:var(--sans);color:var(--muted);font-size:.82rem}
.post-body table{border-collapse:collapse;width:100%;font-family:var(--sans);font-size:.92rem}.post-body th,.post-body td{border-bottom:1px solid var(--line);padding:8px;text-align:left}
/* evidence (F-EVIDENCE  research machine) */
.fact,.interp{font-family:var(--sans);font-size:.95rem;padding:14px 18px;margin:1.4em 0;border:1px solid var(--line);background:var(--panel)}
.fact::before{content:"\10EC \10E7 \10D0 \10E0 \10DD  \00B7  Source";display:block;color:var(--gold);font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;margin-bottom:6px}
.interp{border-style:dashed}.interp::before{content:"\10D8 \10DC \10E2 \10D4 \10E0 \10DE \10E0 \10D4 \10E2 \10D0 \10EA \10D8 \10D0  \00B7  Interpretation";display:block;color:var(--muted);font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;margin-bottom:6px}
.ev{display:inline-block;font-family:var(--sans);font-size:.7rem;border:1px solid var(--gold);color:var(--gold);padding:0 6px;margin-left:4px;vertical-align:middle}
.sources{font-family:var(--sans);font-size:.88rem;color:var(--muted);border-top:1px solid var(--line);margin-top:2.5em;padding-top:1em}
.sources li{margin-bottom:6px}
/* bilingual (F-I18N): <div class="lang-ka"></div><div class="lang-en"></div> */
html[data-lang=ka] .lang-en,html[data-lang=en] .lang-ka{display:none}
/* labels, nav */
.labels{display:flex;gap:8px;flex-wrap:wrap;margin:30px 0}.labels a{border:1px solid var(--line);padding:4px 10px;font-size:.8rem;color:var(--muted)}.labels a:hover{color:var(--gold);border-color:var(--gold)}
.post-nav{display:grid;grid-template-columns:1fr 1fr;gap:16px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:20px 0;margin:30px 0}
.post-nav a{color:var(--gold);font-size:.92rem}.post-nav .next{text-align:right}
.share{display:flex;gap:14px;font-size:.85rem;color:var(--muted)}.share a{color:var(--gold)}
.pager{display:flex;justify-content:space-between;padding:40px 0}.pager a{color:var(--gold)}
/* author (always last) */
.author-card{display:grid;grid-template-columns:120px 1fr;gap:28px;align-items:center;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:32px 0;margin:40px 0}
.author-card img{width:120px;height:120px;border-radius:50%;object-fit:cover;border:1px solid var(--gold)}
.author-card p{margin:4px 0;color:#c7c4b6}
/* comments */
.comments{max-width:760px;margin:0 auto 60px;font-size:.95rem}.comments h3{font-size:1.2rem}
/* footer */
.site-footer{padding:40px 0 60px;color:var(--muted);font-size:.85rem}
.site-footer .wrap{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}
.site-footer a{color:var(--gold)}
.site-footer ul{list-style:none;margin:0;padding:0;display:flex;gap:18px;flex-wrap:wrap}
/* static pages */
.page .post-body > p:first-of-type::first-letter{float:none;font-size:inherit;padding:0;color:inherit}
@media(max-width:720px){.search-form input{width:110px}.author-card{grid-template-columns:1fr}.post-nav{grid-template-columns:1fr}.post-nav .next{text-align:left}.hero{padding:44px 0 34px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}

/* ===== v1.1  richer home ===== */
body{background:radial-gradient(1200px 600px at 80% -10%,rgba(213,185,120,.07),transparent 60%),var(--bg)}
.orn{display:flex;align-items:center;gap:14px;color:var(--gold);font-size:.8rem;letter-spacing:.3em;margin:0 0 18px}.orn::before,.orn::after{content:"";height:1px;background:linear-gradient(90deg,transparent,var(--gold));flex:1;max-width:120px}.orn::after{background:linear-gradient(90deg,var(--gold),transparent)}
.hero-x{position:relative;margin:0 -5.6%;min-height:640px;display:grid;grid-template-columns:1.05fr .95fr;align-items:center;gap:30px;padding:80px 5.6% 70px;overflow:hidden;border-bottom:1px solid var(--line)}
.hero-x .bg{position:absolute;inset:0;background-size:cover;background-position:center 35%;animation:kb 40s ease-in-out infinite alternate;opacity:.55}
.hero-x::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--bg) 8%,rgba(17,17,15,.75) 48%,rgba(17,17,15,.35)),linear-gradient(0deg,var(--bg),transparent 35%)}
.hero-x > *:not(.bg){position:relative;z-index:2}
@keyframes kb{from{transform:scale(1.02)}to{transform:scale(1.12) translate(-1%,1%)}}
.hero-x h1{font-size:clamp(2.4rem,5vw,4.8rem);margin:.1em 0 .4em}
.stats{display:flex;gap:28px;flex-wrap:wrap;margin:28px 0 0;color:var(--muted);font-size:.85rem}.stats b{display:block;font-family:var(--serif);font-weight:400;font-size:1.9rem;color:var(--text)}
.btns{display:flex;gap:14px;flex-wrap:wrap;align-items:center}
.ghost{display:inline-block;border:1px solid var(--line);color:var(--text);padding:13px 20px;font-size:.9rem;min-height:48px}.ghost:hover{border-color:var(--gold);color:var(--gold)}
.fan{position:relative;height:460px;perspective:1200px}
.fan a{position:absolute;left:50%;top:50%;width:190px;margin:-170px 0 0 -95px;transform-origin:50% 120%;transition:transform .5s cubic-bezier(.2,.8,.2,1),filter .3s;filter:drop-shadow(0 18px 30px rgba(0,0,0,.6))}
.fan img{display:block;width:100%;border-radius:8px}
.fan a:nth-child(1){transform:rotate(-24deg) translateX(-150px)}.fan a:nth-child(2){transform:rotate(-12deg) translateX(-75px)}.fan a:nth-child(3){transform:rotate(0) translateY(-14px);z-index:3}.fan a:nth-child(4){transform:rotate(12deg) translateX(75px)}.fan a:nth-child(5){transform:rotate(24deg) translateX(150px)}
.fan a:hover{z-index:5;filter:drop-shadow(0 24px 40px rgba(213,185,120,.35))}
.fan a:nth-child(1):hover{transform:rotate(-24deg) translateX(-150px) translateY(-30px)}.fan a:nth-child(2):hover{transform:rotate(-12deg) translateX(-75px) translateY(-30px)}.fan a:nth-child(3):hover{transform:translateY(-44px) scale(1.04)}.fan a:nth-child(4):hover{transform:rotate(12deg) translateX(75px) translateY(-30px)}.fan a:nth-child(5):hover{transform:rotate(24deg) translateX(150px) translateY(-30px)}
/* pantheon map */
.pantheons{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px}
.pt{border:1px solid var(--line);padding:16px 14px;background:linear-gradient(180deg,var(--panel),transparent);min-height:120px;display:flex;flex-direction:column;justify-content:space-between;transition:border-color .2s,transform .2s}
.pt:hover{border-color:var(--gold);transform:translateY(-3px)}
.pt .num{font-family:var(--serif);color:var(--gold);font-size:1.3rem}.pt .nm{font-family:var(--serif);font-size:1.1rem;line-height:1.3}
.st{font-size:.68rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}.st.live{color:var(--gold)}.st.live::before{content:"\25CF  "}
/* rich work cards */
.works{grid-template-columns:repeat(auto-fill,minmax(300px,1fr))}
.work{position:relative;overflow:hidden;min-height:330px;justify-content:flex-end}
.work img{position:absolute;inset:0;height:100%;aspect-ratio:auto;transition:transform 1.2s ease;opacity:.85}
.work::after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(17,17,15,.96) 18%,rgba(17,17,15,.2) 70%)}
.work:hover img{transform:scale(1.06)}
.work-body{position:relative;z-index:2}.work-body .go{color:var(--gold);font-size:.85rem;margin-top:10px;display:inline-block}
.work.wide{grid-column:span 2}
/* quote band */
.quote-band{padding:80px 0;text-align:center;border-bottom:1px solid var(--line)}
.quote-band blockquote{font-family:var(--serif);font-size:clamp(1.5rem,2.6vw,2.3rem);line-height:1.5;max-width:900px;margin:0 auto 16px}
.quote-band cite{color:var(--muted);font-style:normal;font-size:.85rem;letter-spacing:.08em}
/* split band (music / author) */
.split{display:grid;grid-template-columns:1fr 1fr;gap:0;border-bottom:1px solid var(--line);margin:0 -5.6%}
.split .img{min-height:420px;background-size:cover;background-position:center}
.split .txt{padding:60px 5.6%;display:flex;flex-direction:column;justify-content:center;background:var(--panel)}
.author-band{display:grid;grid-template-columns:200px 1fr;gap:44px;align-items:center;padding:64px 0;border-bottom:1px solid var(--line)}
.author-band img{width:200px;height:200px;border-radius:50%;object-fit:cover;border:1px solid var(--gold)}
@media(max-width:900px){.hero-x{grid-template-columns:1fr;min-height:0}.fan{height:380px;transform:scale(.8)}.split{grid-template-columns:1fr}.work.wide{grid-column:auto}.author-band{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.hero-x .bg{animation:none}}
/* ===== v1.4  balanced home ===== */
.hero-y{display:grid;grid-template-columns:1.05fr .95fr;gap:48px;align-items:center;margin:0 -5.6%;padding:72px 5.6% 64px;border-bottom:1px solid var(--line);background:radial-gradient(800px 420px at 85% 30%,rgba(127,184,176,.07),transparent 60%),radial-gradient(700px 420px at 10% 0,rgba(213,185,120,.08),transparent 60%)}
.hero-y h1{font-size:clamp(2.4rem,5vw,4.6rem);margin:.1em 0 .4em}
.mosaic{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.tile{position:relative;aspect-ratio:4/5;overflow:hidden;border:1px solid var(--line);background:var(--panel);display:block;transition:border-color .2s,transform .3s}
.tile:hover{border-color:var(--gold);transform:translateY(-4px)}
.tile img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.8;transition:transform 1.2s ease}
.tile:hover img{transform:scale(1.07)}
.tile::after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(17,17,15,.92) 8%,transparent 55%)}
.tile>span{position:absolute;left:12px;bottom:10px;z-index:2;font-family:var(--serif);font-size:1.05rem}
.globe-css{position:absolute;left:50%;top:44%;width:62%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle at 35% 30%,rgba(213,185,120,.35),transparent 55%),radial-gradient(rgba(213,185,120,.55) 1px,transparent 1.6px) 0 0/9px 9px,#15140f;box-shadow:0 0 40px rgba(213,185,120,.25),inset -14px -10px 30px rgba(0,0,0,.7);animation:spin 40s linear infinite}
@keyframes spin{from{background-position:0 0,0 0,0 0}to{background-position:0 0,180px 0,0 0}}
.bars{position:absolute;left:14%;right:14%;top:22%;bottom:34%;display:flex;align-items:flex-end;gap:7%}
.bars b{flex:1;background:linear-gradient(0deg,var(--gold),rgba(127,184,176,.7));height:30%;animation:eq 1.6s ease-in-out infinite alternate}
.bars b:nth-child(2){animation-delay:-.4s}.bars b:nth-child(3){animation-delay:-.9s}.bars b:nth-child(4){animation-delay:-.2s}.bars b:nth-child(5){animation-delay:-1.1s}.bars b:nth-child(6){animation-delay:-.6s}.bars b:nth-child(7){animation-delay:-1.4s}
@keyframes eq{from{height:18%}to{height:96%}}
.intro{max-width:760px;margin:-6px 0 18px}
.work.noimg{background:radial-gradient(400px 220px at 70% 20%,rgba(213,185,120,.1),transparent 60%),var(--panel)}
.work.noimg::after{display:none}
.glyph{position:absolute;inset:0 0 40% 0;display:flex;align-items:center;justify-content:center;font-family:var(--serif);font-style:normal;font-size:3.4rem;color:var(--gold);opacity:.85}
.glyph .globe-css{width:46%;top:50%}
.glyph .bars{top:22%;bottom:22%}
.atlas-band{display:grid;grid-template-columns:.9fr 1.1fr;gap:40px;align-items:center}
.ab-globe{position:relative;aspect-ratio:1/1;max-height:560px;border:1px solid var(--line);background:radial-gradient(circle,#1b1a14 0,var(--bg) 65%)}
.ab-globe iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
.pt-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px;margin:20px 0 24px}
.pt-mini{border:1px solid var(--line);padding:8px 10px;display:grid;grid-template-columns:auto 1fr;gap:2px 10px;align-items:center;font-size:.9rem}
a.pt-mini:hover{border-color:var(--gold)}
.pt-mini .num{font-family:var(--serif);color:var(--gold);grid-row:span 2}
.pt-mini .st{font-size:.62rem}
.steps{list-style:none;padding:0;margin:0 0 24px;display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;counter-reset:none}
.steps li{border-top:1px solid var(--gold);padding:14px 4px 0}
.steps b{font-family:var(--serif);font-weight:400;color:var(--gold);font-size:1.4rem}
.steps h3{margin:4px 0 4px;font-size:1.15rem}.steps p{margin:0;color:var(--muted);font-size:.9rem}
.evidence{border:1px solid var(--line);padding:18px 20px;background:var(--panel);display:flex;justify-content:space-between;gap:20px;align-items:center;flex-wrap:wrap}
.evidence p{margin:0;max-width:820px;color:var(--muted)}
@media(max-width:900px){.hero-y,.atlas-band{grid-template-columns:1fr}.mosaic{grid-template-columns:repeat(2,1fr)}}
@media(prefers-reduced-motion:reduce){.globe-css,.bars b{animation:none}}
/* ===== v1.5  start here, music, follow ===== */
.start-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.start-card{border:1px solid var(--line);background:var(--panel);padding:20px 20px 22px;display:block;transition:border-color .2s,transform .2s}
.start-card:hover{border-color:var(--gold);transform:translateY(-3px)}
.start-card b{font-family:var(--serif);font-weight:400;color:var(--gold);font-size:1.5rem;display:block}
.start-card .tag{font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.start-card h3{margin:.3em 0 .3em}.start-card p{margin:0;color:var(--muted);font-size:.92rem}
.next-up{margin:18px 0 0;color:var(--muted);font-size:.92rem;display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.next-up .dot{width:8px;height:8px;border-radius:50%;background:var(--gold);box-shadow:0 0 0 4px rgba(213,185,120,.15)}
.music-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:36px;align-items:center}
.music-video{position:relative;aspect-ratio:16/9;border:1px solid var(--line);background:#000}
.music-video iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
.vlist{list-style:none;padding:0;margin:14px 0 20px}.vlist li{border-top:1px solid var(--line)}
.vlist a{display:block;padding:8px 0;color:var(--text)}.vlist a:hover{color:var(--gold)}
.pillar.empty{opacity:.55}.pillar.empty::after{content:"Soon";display:inline-block;margin-top:8px;font-size:.66rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.post-body .lang-switch{margin:0 0 1.2em;font-size:.85rem}.post-body .lang-switch a{border:1px solid var(--line);padding:4px 12px;color:var(--gold)}
.post-body .lede{font-size:1.18rem;line-height:1.75;color:var(--text)}
.post-body figure{margin:1.6em 0}.post-body figcaption{font-size:.8rem;color:var(--muted);margin-top:6px}
.post-body ol.sources{font-size:.9rem;color:var(--muted)}.post-body .made{font-size:.85rem;color:var(--muted);border-top:1px solid var(--line);padding-top:12px;margin-top:2em}
@media(max-width:900px){.start-grid,.music-grid{grid-template-columns:1fr}}



/* legacy post content guard */
html,body{overflow-x:hidden}
.post-body{overflow-wrap:anywhere}.post-body *{max-width:100%!important;box-sizing:border-box}
.post-body img{height:auto!important}.post-body .separator a{margin:0!important}
.post-body iframe{width:100%!important;aspect-ratio:16/9;height:auto!important}
.post-body table{display:block;overflow-x:auto}

/* pillars */
.pillars{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}
.pillar{border:1px solid var(--line);padding:22px 18px;background:linear-gradient(180deg,var(--panel),transparent);transition:border-color .2s,transform .2s}
.pillar:hover{border-color:var(--gold);transform:translateY(-3px)}
.pillar .num{font-family:var(--serif);color:var(--gold);font-size:1.4rem}.pillar h3{margin:8px 0 6px;font-size:1.15rem;line-height:1.35}.pillar p{margin:0;color:var(--muted);font-size:.88rem}
@media(max-width:1000px){.pillars{grid-template-columns:repeat(2,1fr)}}
/* contact form */
.contact-wrap{max-width:760px;margin:0 auto 60px}.contact-wrap label{display:block;margin:0 0 16px;color:var(--muted);font-size:.85rem}
.contact-wrap input[type=text],.contact-wrap input[type=email],.contact-wrap textarea{display:block;width:100%;margin-top:6px;background:var(--panel);border:1px solid var(--line);color:var(--text);padding:12px;font:inherit}
.contact-wrap input:focus,.contact-wrap textarea:focus{border-color:var(--gold);outline:none}
.contact-form-success-message{color:var(--gold)}.contact-form-error-message{color:#e08a7a}
.menu ul{gap:18px}

body.script:
//
(function(){
  var root=document.documentElement,key='ill-lang',lang='ka';
  try{var st=localStorage.getItem(key);lang=st||((navigator.language||'').slice(0,2)==='ka'?'ka':'en');}catch(e){}
  function set(l){root.setAttribute('data-lang',l);document.querySelectorAll('[data-set-lang]').forEach(function(b){b.setAttribute('aria-pressed',b.getAttribute('data-set-lang')===l)});try{localStorage.setItem(key,l)}catch(e){}}
  set(lang);
  document.querySelectorAll('[data-set-lang]').forEach(function(b){b.addEventListener('click',function(){set(b.getAttribute('data-set-lang'))})});
  var cb=document.getElementById('contact-box');if(cb&&/\/p\/contact\.html/.test(location.pathname))cb.style.display='block';
  // active menu item
  document.querySelectorAll('.menu a').forEach(function(a){if(location.href.indexOf(a.getAttribute('href'))>-1)a.classList.add('active')});
  // works filter (F-CATALOG)
  document.querySelectorAll('.filters button').forEach(function(btn){btn.addEventListener('click',function(){
    var f=btn.getAttribute('data-filter');btn.parentNode.querySelectorAll('button').forEach(function(x){x.setAttribute('aria-pressed',x===btn)});
    document.querySelectorAll('.work').forEach(function(w){w.style.display=(f==='all'||w.getAttribute('data-kind')===f)?'':'none'})})});
  // mosaic tiles pick a filter
  document.querySelectorAll('[data-pick]').forEach(function(a){a.addEventListener('click',function(){var b=document.querySelector('.filters button[data-filter="'+a.getAttribute('data-pick')+'"]');if(b)b.click()})});
  // live article count
  var pc=document.getElementById('ill-post-count');
  if(pc&&window.fetch){fetch('/feeds/posts/summary?alt=json&max-results=0').then(function(r){return r.json()}).then(function(d){pc.textContent=d.feed.openSearch$totalResults.$t}).catch(function(){})}
  // empty pillars: label with no posts -> marked Soon, not a dead end
  if(window.fetch){document.querySelectorAll('a.pillar').forEach(function(a){var m=(a.getAttribute('href')||'').match(/\/search\/label\/(.+)$/);if(!m)return;
    fetch('/feeds/posts/summary/-/'+m[1]+'?alt=json&max-results=0').then(function(r){return r.json()}).then(function(d){if(+d.feed.openSearch$totalResults.$t===0){a.classList.add('empty');a.setAttribute('aria-disabled','true');a.removeAttribute('href')}}).catch(function(){})})}
  // reading time + progress (F-PROGRESS)
  var body=document.getElementById('post-body'),rt=document.getElementById('read-time'),bar=document.getElementById('read-progress');
  if(body&&rt){var w=(body.innerText||'').split(/\s+/).length;rt.textContent=Math.max(1,Math.round(w/200))+' min';}
  if(body&&bar){window.addEventListener('scroll',function(){var r=body.getBoundingClientRect(),h=r.height-innerHeight;bar.style.width=Math.min(100,Math.max(0,(-r.top)/Math.max(1,h)*100))+'%'},{passive:true});}
})();
//
